insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('79323bc5-6670-5774-87bb-26122755d85a', '818cfaf6-90b5-5366-ad8c-e8a89fa09b79', 'As used in the text, what does the word "undergone" most nearly mean?', '["Neglected", "Enjoyed", "Conveyed", "Endured"]'::jsonb, 1, 'The following text is adapted from Anton Chekhov’s 1904 play The Cherry Orchard (translated by Julius West in 1916).

TROFIMOV: Believe me, Anya, believe me! I’m not thirty yet, I’m young. I’m still a student, but I have <u>undergone</u> a great deal! I’m as hungry as the winter, I’m ill, I’m shaken... and where haven’t I been—fate has tossed me everywhere!'),
  ('70518688-2662-5099-a4a6-aaef110cb570', '818cfaf6-90b5-5366-ad8c-e8a89fa09b79', 'Which choice completes the text with the most logical and precise word or phrase?', '["concludes", "explains", "precedes", "shows"]'::jsonb, 2, 'Indigenous Photograph is an organization whose mission is to ensure that images of indigenous peoples in the media are presented from indigenous perspectives. The organization _____ this commitment by promoting the works of artist Geremew Tigabu (Ethiopian, Amhara, and Tigre) and other prominent indigenous photographers who document and reflect Indigenous lives and experiences.'),
  ('7adfd137-59b8-52e3-86ce-ea7d0ed869b5', '818cfaf6-90b5-5366-ad8c-e8a89fa09b79', 'Which choice completes the text with the most logical and precise word or phrase?', '["designate", "nurture", "preclude", "assess"]'::jsonb, 3, 'Although fewer companies trade their stocks on the Cambodia Securities Exchange in Phnom Penh, Cambodia, than on the stock exchanges in London, Mumbai, or Tokyo, the Cambodia Securities Exchange has the advantage of being able to _____ relatively small companies in Cambodia: by connecting those companies to investors with expertise about the country’s economic conditions, the Cambodia Securities Exchange can help those companies thrive.'),
  ('6a48d633-7c39-5882-9c19-2b4ef0ebdcd0', '818cfaf6-90b5-5366-ad8c-e8a89fa09b79', 'Which choice completes the text with the most logical and precise word or phrase?', '["understand", "advance", "counteract", "accentuate"]'::jsonb, 4, 'The emphasis on accurately representing the experiences of average working people that is characteristic of the realist style can be seen in The Gleaners, painted by Jean-Francois Millet, which depicts peasants picking stray wheat from a field after the harvest. This style can thus be seen as an effort to _____ what were regarded as the excesses of the romantic style evident in many paintings by Horace Vernet, which instead exaggerated their subjects'' beauty or heroism while hiding all imperfection.'),
  ('43216bc3-6af5-5a7d-9f05-c3fa38678457', '818cfaf6-90b5-5366-ad8c-e8a89fa09b79', 'Which choice completes the text with the most logical and precise word or phrase?', '["a consequence", "an explanation", "a repudiation", "an objective"]'::jsonb, 5, 'The swordfish can swim very fast—up to 97 kilometers per hour (km/hr)—but it is significantly slower than the frigatebird, which can fly at speeds up to 153 km/hr. The difference between these speeds is largely _____ of the fact that the features that make flight possible do less to limit top speeds than the features suitable for swimming through water.'),
  ('46950318-a3ae-556c-8d62-23b2d8e09f85', '818cfaf6-90b5-5366-ad8c-e8a89fa09b79', 'Which choice best describes the function of the underlined sentence in the text as a whole?', '["It presents an accomplishment of a historical figure whose significance is detailed later in the text.", "It describes a common perception of a historical figure that is challenged by information presented later in the text.", "It states a claim about a historical figure that is supported by evidence later in the text.", "It compares the achievements of three historical figures to a fourth that is mentioned later in the text."]'::jsonb, 6, '<u>President Richard Nixon is most famous for his participation in the 1970s Watergate political scandal, a</u> <u>convoluted tale of criminality and eroded ethics involving a constellation of associates such as security</u> <u>operative Jack Caulfield and Attorney General John Mitchell.</u> But Nixon’s legacy is complex: he has been praised for his role in affirming the sovereignty of tribal nations, and he once made an attempt at reforming United States health care policy that is arguably a precursor to the Affordable Care Act, which became law during the Barack Obama administration.'),
  ('b759d5f4-bd19-5c1d-8642-bb29448416c3', '818cfaf6-90b5-5366-ad8c-e8a89fa09b79', 'Which choice best describes the function of the underlined sentence in the text as a whole?', '["It suggests improvements to a particular tribal cultural center.", "It encourages tribal citizens to attend their local cultural center.", "It explains how one tribal cultural center differs from other tribal cultural centers.", "It provides a basic description of a particular tribal cultural center."]'::jsonb, 7, 'In what is now Washington state, the Tulalip Tribes operate the Hibulb Cultural Center. <u>Relying on</u> <u>traditional knowledge to guide the design of exhibits, this institution presents Tulalip history and culture</u> <u>to the tribes'' citizens.</u> The Comanche Nation, a tribe in Oklahoma, employs a similar strategy in its own cultural center. Both centers contrast with museums that aren’t Indigenous-led; when displaying Indigenous artifacts, such museums tend to anticipate mainly non-Indigenous audiences and rely on Euro-centric strategies for designing exhibits.'),
  ('ebe72d19-de7c-56fe-9aea-d452b8a4e8e4', '818cfaf6-90b5-5366-ad8c-e8a89fa09b79', 'Which choice best describes the function of the underlined sentence in the text as a whole?', '["It identifies a feature of many video games that is not shared by some of the games included in MOMA’s exhibition.", "It provides a claim about video games as art that both MOMA and the author accept as true.", "It describes a misconception about video games that the author believes is evident in MOMA’s choice about which video games to exhibit.", "It presents a consideration that the author thinks partly undermines MOMA’s approach to exhibiting video games."]'::jsonb, 8, 'The Museum of Modern Art (MOMA) in New York City has an exhibition of video games that includes Pac-Man from 1980, which museum visitors can play on site, and SimCity 2000 from 1994, which visitors can see only in a video presentation. MOMA claims the video presentations are only for games that would be impractical to display in a playable form, but <u>video games are an inherently interactive medium</u>, a feature that is grossly absent in a video-only presentation.'),
  ('37f8361f-4745-5ac5-82b9-01f8c858043a', '818cfaf6-90b5-5366-ad8c-e8a89fa09b79', 'The text makes which point about the O''odham word gogogs?', '["It contains a repetition of the element \"go\" in gogs.", "It doesn’t have a clear equivalent in English.", "It is the only word in O''odham that uses reduplication.", "It is identical in meaning to several other words in O''odham."]'::jsonb, 9, 'In O''odham, an Indigenous language from the Southwest region of what is now the United States, gogs means "a dog", whereas gogogs is used to refer to several dogs. This phenomenon, in which an element of a root word is repeated, sometimes with modification, within another word that is related to the root word, is called reduplication. In this case, the element "go" in gogs gets repeated in gogogs. There are many examples of this type of reduplication in O''odham.'),
  ('54c86ddd-6065-5abf-8a0a-dc25eb6f4ae3', '818cfaf6-90b5-5366-ad8c-e8a89fa09b79', 'Which choice best states the main purpose of the text?', '["The unusual structure that O''Brian uses for Master and Commander makes it one of his most intricate books.", "Critics have differing views regarding the efficacy of the structures of the novels in the Aubrey Maturin series.", "Some critics think the Aubrey/Maturin series should have the literary renown of The Forsyte Saga, while others disagree.", "Many critics judge the Aubrey/Maturin novels to be remarkably entertaining despite flaws in the novels'' structures."]'::jsonb, 10, 'Master and Commander, first published in 1969, is a novel in Patrick O''Brian’s Aubrey Maturin series, which includes twenty completed books. Some critics have found fault with the abrupt endings of Master and Commander and other books in the series, saying that they do not finish conclusively but arbitrarily stop. Other critics, however, argue that the books should not be thought of as discrete texts with traditional beginnings and endings but as a single incredibly long work, similar to other multivolume stories, such as John Galsworthy’s The Forsyte Saga.'),
  ('04ae6d34-4bca-516c-aae9-762d6a0e3d9d', '818cfaf6-90b5-5366-ad8c-e8a89fa09b79', 'Which quotation from "The Monster" most effectively illustrates the claim?', '["\"After some trouble [Jim’s father] found the subject of the incident, the broken flower. Turning then, he saw the child lurking at the rear and scanning his countenance.\"", "\"[Jim’s father] was shaving this lawn as if it were a priest’s chin. All during the season he had worked at it in the coolness and peace of the evenings after supper. Even in the shadow of the cherry trees the grass was strong and healthy.\"", "\"[Jim’s father] paused, and with the howl of the machine no longer occupying the sense, one could hear the robins in the cherry trees arranging their affairs.\"", "\"[Jim] went on to the lawn, very slowly, and kicking wretchedly at the turf. Presently his father came along with the whirring machine, while the sweet, new grass blades spun from the knives.\""]'::jsonb, 11, '"The Monster" is an 1898 story by Stephen Crane. In the story, the character of Jim, a young boy, accidentally damages a peony (a flower) in the yard while his father is tending to the lawn. Crane depicts the dedication and care with which his father typically cares for his lawn, writing,

_____'),
  ('9ae3eccd-55e0-5646-820b-fc87024472bf', '818cfaf6-90b5-5366-ad8c-e8a89fa09b79', 'Which choice best describes data from the graph that support the student’s claim?', '["While the number of hours of traffic delay per commuter per year was always lower in the Allentown-Bethlehem, Pennsylvania area than in the New York City, New York area for each year between 1990 and 2000, the amount of traffic delay rose in both areas during this period.", "In at least one of the three urban areas shown, the amount of traffic delay was less than 20 hours per person per year at one point between 1990 and 2000.", "In 1992, the amount of traffic delay in the New York City, New York area was less than 20 hours per commuter per year.", "Throughout the period between 1990 and 2000, the annual amount of traffic delay per commuter was greater in the Allentown-Bethlehem, Pennsylvania area than in the New York City, New York area."]'::jsonb, 12, '![figure](/q/jun23/001.webp)

In a college course on urban affairs, a student asserts that increased traffic congestion in the 1990s in the United States was present both in very large cities such as New York City, New York, and smaller areas such as Allentown-Bethlehem, Pennsylvania, and Beaumont, Texas; though those smaller areas may have been less affected by traffic congestion than very large cities, this congestion also worsened in them over time.'),
  ('fcf7dcff-4667-54a0-b889-88304a7e8c97', '818cfaf6-90b5-5366-ad8c-e8a89fa09b79', 'Which finding, if true, would most directly support Alegado and colleagues'' conclusion?', '["Bowman and Ahmed found that S. rosetta tended to form colonies after bacterial exposure.", "Bowman found that S. rosetta tended to form colonies after bacterial exposure, but Ahmed did not.", "Ahmed found that S. rosetta tended to form colonies after bacterial exposure, but Bowman did not.", "Neither Bowman nor Ahmed found that S. rosetta tended to form colonies after bacterial exposure."]'::jsonb, 13, 'Biologist Rosanna Alegado believes that we might learn how multicellular organisms developed from single-celled ones if we understand why the single-celled organism Salpingoeca rosetta, the oldest living relative of animals, sometimes forms colonies of cells. Alegado and colleagues reviewed data from many studies of how S. rosetta responds when exposed to another type of single-celled organism, bacteria, including John P. Bowman’s work with Algoriphagus ratkowskyi bacteria and Iftikhar Ahmed’s work with Algoriphagus boritolerans bacteria. Alegado and colleagues concluded that both A. ratkowskyi and A. boritolerans might have played a role in the development of multicellular organisms.'),
  ('76562491-5202-5368-b61e-ee2ad072658d', '818cfaf6-90b5-5366-ad8c-e8a89fa09b79', 'Which finding, if true, would most directly support Alegado and colleagues'' conclusion?', '["S. rosetta tended to form colonies when exposed to V. fischeri and when exposed to B. fragilis.", "S. rosetta tended to form colonies when exposed to V. fischeri, but not when exposed to B. fragilis.", "S. rosetta tended to form colonies when exposed to B. fragilis, but not when exposed to V. fischeri.", "S. rosetta did not tend to form colonies when exposed to either V. fischeri or B. fragilis."]'::jsonb, 14, 'Biologist Rosanna Alegado believes that we might learn how multicellular organisms developed from single-celled ones if we understand why the single-celled organism Salpingoeca rosetta, the oldest living relative of animals, sometimes forms colonies of cells. Alegado and colleagues reviewed data from many studies about how S. rosetta responds when exposed to another type of single-celled organism, bacteria, including Edward G. Ruby’s work with Vibrio fischeri bacteria and Ana M. Cerdeño-Tárraga’s work with Bacteroides fragilis bacteria. Alegado and colleagues concluded that neither V. fischeri nor B. fragilis are likely to have played a significant role in the development of multicellular organisms.'),
  ('3e7612ca-f0e8-5f1c-971b-d7d14006c813', '818cfaf6-90b5-5366-ad8c-e8a89fa09b79', 'Which choice most logically completes the text?', '["<u>A</u> there was a gradual increase in the genetic homogeneity of Mammillaria species in states neighboring Tamaulipas.", "<u>B</u>Mammillaria species other than M. anniana would become more common in Tamaulipas.", "<u>C</u> several other Mammillaria species could survive in Tamaulipas in the future.", "<u>D</u> the genetic homogeneity of M. anniana decreased over time."]'::jsonb, 15, 'Previous research has shown that plant species with a narrow geographical range tend to be more genetically homogeneous than plant species with extensive ranges are. Based on these findings, researchers recently ran simulations to predict how the genetic variation of several species of Mammillaria, a genus of cactus found throughout the Americas, might change in different distribution conditions. One of these species, M. anniana, is found only in the state of Tamaulipas. The researchers simulated what would happen if M. anniana spread to new habitats outside Tamaulipas, and, consistent with previous findings, the results showed that _____'),
  ('74e83b8b-8cdd-5615-84b4-508b0e4d6d49', '818cfaf6-90b5-5366-ad8c-e8a89fa09b79', 'Which choice completes the text so that it conforms to the conventions of standard English?', '["discussing", "discusses", "to discuss", "having discussed"]'::jsonb, 16, 'In the periodic table, an element’s atomic number indicates the number of protons in an atom of that element. For example, there are 25 protons in a manganese atom. Raymond Chang’s textbook General Chemistry: The Essential Concepts _____ this concept in detail.'),
  ('2adcef42-c8b4-505b-8e43-19ecd4c4f16f', '818cfaf6-90b5-5366-ad8c-e8a89fa09b79', 'Which choice completes the text so that it conforms to the conventions of standard English?', '["served", "had served", "serves", "was serving"]'::jsonb, 17, 'An emulsifier is a type of compound that _____ to stabilize an emulsion—a mixture of two or more liquids that otherwise would not easily blend together. In the cosmetics industry, emulsifiers like cetostearyl alcohol are commonly used to blend oil and water into homogeneous formulations, like lotions and perfumes.'),
  ('e806d65f-1f93-504f-8853-a8f6a8e64761', '818cfaf6-90b5-5366-ad8c-e8a89fa09b79', 'Which choice completes the text so that it conforms to the conventions of standard English?', '["list: the", "list. The", "list; the", "list the"]'::jsonb, 18, 'Over the years, dozens of architectural and archaeological sites important to Hawaiian history and culture—such as Grove Farm, Kilauea School, and the Hana Belt Road—have been added to an important _____ Hawai''i Register of Historic Places. New sites are added each year, as decided by a review board of experts including sociologist Alton Okinaka, architect Katle Stephens, and historian Bill Souza.'),
  ('a6ad3f61-7f81-59da-9970-a3e3f53f029a', '818cfaf6-90b5-5366-ad8c-e8a89fa09b79', 'Which choice completes the text so that it conforms to the conventions of standard English?', '["restaurants", "restaurants;", "restaurants and", "restaurants,"]'::jsonb, 19, 'Today, the Michelin Guide is widely known as the arbiter of fine dining, but when it was created in 1990, it was little more than a marketing gimmick. Brothers Andre and Edouard Michelin sought to increase profits for their tire company by encouraging their customers to drive across France, visiting the guide’s recommended hotels and _____ as it grew in scope and influence, the guide had its modest French eateries replaced with the best restaurants from around the world, including The Eight in Macau and Sushi Ueda in Nagoya.'),
  ('412c8458-579d-56a1-8571-f89915692591', '818cfaf6-90b5-5366-ad8c-e8a89fa09b79', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["economists Laura Gee and Muriel Niederle,", "economists Laura Gee and Muriel Niederle", "economists Laura Gee, and Muriel Niederle,", "economists, Laura Gee and Muriel Niederle,"]'::jsonb, 20, 'In their research, behavioral _____ integrate methods from psychology and economics to analyze how and why people make particular choices and to examine the broader implications of those choices for the economy.'),
  ('aa92079b-c811-5f0a-9a6c-998df0d7bfd1', '818cfaf6-90b5-5366-ad8c-e8a89fa09b79', 'Which choice completes the text with the most logical transition?', '["Still,", "By contrast,", "For example,", "Instead,"]'::jsonb, 21, 'The city of Jinan, China, expanded its rapid transit system, the Jinan Metro, as recently as 2020. _____ the system will likely need to undergo further expansions as the size and needs of the city’s population shift.'),
  ('83867587-4f11-5328-8b64-bd5c4ed522f9', '818cfaf6-90b5-5366-ad8c-e8a89fa09b79', 'Which choice completes the text with the most logical transition?', '["Nevertheless,", "Therefore,", "Furthermore,", "Next,"]'::jsonb, 22, 'Theater industry veteran Robert Tang admits that his ambitions weren’t very lofty when he created the Asian American Theater Revue, a website that documents information about Asian American theaters like Second Generation Productions in New York City, New York: "Everyone had a site, so I had to have one, too." _____ his site has become an essential resource for industry professionals looking to learn more about Asian American plays, playwrights, theater festivals, and more.'),
  ('936463e5-3d4f-52b2-a42a-7a411f0bd081', '818cfaf6-90b5-5366-ad8c-e8a89fa09b79', 'Which choice completes the text with the most logical transition?', '["rather,", "as a result,", "similarly,", "finally,"]'::jsonb, 23, 'The first documented use of the English word "session" is attributed to poet Geoffrey Chaucer’s 1386 work Canterbury Prologue. However, Chaucer didn’t write in Modern English; _____ he wrote in what we now call Middle English, which was commonly used during the period.'),
  ('09be0928-3a4c-5a3a-8ec6-89b7c662e501', '818cfaf6-90b5-5366-ad8c-e8a89fa09b79', 'The student wants to make and support a claim that kale is a better source of vitamin C than blueberries are. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Kale contains ascorbic acid (which humans cannot make in their bodies), and blueberries do too.", "Blueberries contain 10 mg of vitamin C per 100 g, but kale is a better source of vitamin C; in fact, kale contains 120 mg per 100 g.", "Kale is a better source of vitamin C, also known as ascorbic acid, than blueberries are.", "Humans must get vitamin C from foods like kale and blueberries because they cannot make it in their bodies."]'::jsonb, 24, 'While researching a topic, a student has taken the following notes:

Kale is a vegetable that contains ascorbic acid, an essential nutrient for humans.
Blueberries are fruits that contain ascorbic acid.
There is 120 milligrams (mg) of ascorbic acid per every 100 grams (g) of kale.
There is 10 mg of ascorbic acid per every 100 g of blueberries.
Humans cannot make ascorbic acid in their bodies, so they must get it from foods, including fruits and vegetables.
Ascorbic acid is also known as vitamin C.'),
  ('8326192d-a21c-5b45-a359-f5be100c1414', '818cfaf6-90b5-5366-ad8c-e8a89fa09b79', 'The student wants to explain how hard apatite is in relation to other minerals. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["In the Mohs scale of mineral hardness, topaz (8) is ranked higher than calcite (3).", "Calcite, topaz, and apatite can be ordered by their ability to leave visible scratches on other minerals.", "Topaz has a Mohs scale number of 8, which means that it can scratch not only calcite but also apatite.", "Apatite has a Mohs scale number of 5, which means that it is harder than calcite (3) but softer than topaz (8)."]'::jsonb, 25, 'While researching a topic, a student has taken the following notes:

The Mohs scale of mineral hardness is a ten-point scale that orders minerals by hardness based on their ability to scratch other minerals.
Minerals with larger numbers are harder than minerals with smaller numbers and can leave visible scratches on them.
Minerals with smaller numbers are softer than minerals with larger numbers and cannot leave visible scratches on them.
The mineral calcite has a Mohs scale number of 3.
The mineral apatite has a Mohs scale number of 5.
The mineral topaz has a Mohs scale number of 8.'),
  ('cbeef642-b587-5eec-a788-3f78935d78ad', '818cfaf6-90b5-5366-ad8c-e8a89fa09b79', 'The student wants to emphasize a difference between the two novels. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["The French author Jean-Jacques Rousseau and the American author Sharon Creech have written epistolary novels.", "While Julie, or The New Heloise and Absolutely Normal Chaos are both epistolary novels, the former is composed primarily of letters and the latter of journal entries.", "Some epistolary novels consist primarily of journal entries, but most, like Jean-Jacques Rousseau’s Julie, or The New Heloise, consist primarily of letters.", "Jean-Jacques Rousseau’s Julie, or The New Heloise and Sharon Creech’s Absolutely Normal Chaos demonstrate the variety of documents that can be used in epistolary novels."]'::jsonb, 26, 'While researching a topic, a student has taken the following notes:

Epistolary novels are novels written primarily as a series of fictional documents, typically letters. Sometimes, the documents are journal entries, newspaper clippings, and more.
Julie, or The New Heloise (1761) is an epistolary novel by French author Jean-Jacques Rousseau. It consists primarily of letters sent between a man and a woman in a small French town. Absolutely Normal Chaos (1990) is an epistolary novel by American author Sharon Creech. It consists primarily of journal entries written by a student during her summer vacation.'),
  ('efccb86f-82ea-5870-9a6d-365208a999f4', '818cfaf6-90b5-5366-ad8c-e8a89fa09b79', 'The student wants to compare the number of native and non-native species catalogued. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Seeds from Leptocophylla tameiameiae and Passiflora suberosa can be found in Oahu, Hawaii, but only the former plant is native.", "In 2019, researchers catalogued native and non-native plant seeds found in fecal samples from non-native birds.", "Most of the birds in Oahu, Hawaii, are non-native, and researchers have concluded that they play a vital role in seed dispersal.", "When cataloguing plant seeds found in bird fecal samples, researchers found more non-native seed species than native species."]'::jsonb, 27, 'While researching a topic, a student has taken the following notes:

Most of the plant and bird species in Oahu, Hawaii, are non-native.
In a 2019 study, researchers wanted to know what role non-native birds play in dispersing plant seeds in Oahu.
Researchers catalogued plant seeds found in fecal samples from nonnative birds.
Leptocophylla tameiameiae, a flowering shrub, was one of fifteen native species catalogued. Passiflora suberosa, an herbaceous vine, was one of twenty-nine non-native species catalogued. Researchers concluded that non-native birds play a vital role in dispersing the seeds of native and non-native plants.')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('79323bc5-6670-5774-87bb-26122755d85a', 3, null, '**Choice D is correct.** In this context Trofimov says he has "undergone a great deal" and then describes hardship: "I’m as hungry as the winter, I’m ill, I’m shaken... fate has tossed me everywhere!" Those details show he has suffered and experienced difficult things, so "undergone" here means to have endured or experienced hardship.
**Choice A is incorrect.** "Neglected" means ignored or not cared for, but the passage emphasizes Trofimov’s active experience of hardship rather than being ignored.
**Choice B is incorrect.** "Enjoyed" is the opposite of the passage’s description of suffering; the following clauses make clear his experiences were unpleasant.
**Choice C is incorrect.** "Conveyed" means communicated or transported; nothing in the context suggests Trofimov is saying he has been communicated or carried information—he is describing hardships he has experienced.
**Faster approach:** Use immediate context clues (the words that follow the target word) to find a synonym; here the list of hardships signals a meaning like "endured/experienced."'),
  ('70518688-2662-5099-a4a6-aaef110cb570', 3, null, '**Choice D is correct.** The sentence describes how the organization acts to fulfill its mission: promoting the works of indigenous artists is an action that makes the commitment visible. The verb "shows" precisely links the stated commitment to the means by which it is displayed: "The organization shows this commitment by promoting..."
**Choice A is incorrect.** "Concludes" means to finish or infer; it does not make sense with "by promoting," which indicates an ongoing action that demonstrates commitment rather than an ending or a deduction.
**Choice B is incorrect.** "Explains" would mean the organization gives a verbal or written account of its commitment; promoting artwork does not primarily serve to explain the commitment, so this choice is not the best fit.
**Choice C is incorrect.** "Precedes" means comes before; it would imply the organization comes before the commitment, which is illogical in this context and does not fit the causal phrasing "by promoting."
**Faster approach:** Look for a verb that logically connects a stated commitment with an action that makes that commitment visible—"shows" (demonstrates) is the best concise match.'),
  ('7adfd137-59b8-52e3-86ce-ea7d0ed869b5', 1, null, '**Choice B is correct.** The sentence says the exchange can connect relatively small companies to investors who know the country’s economic conditions and so "help those companies thrive." "Nurture" precisely means to encourage growth and development, matching the idea of supporting companies so they prosper.
**Choice A is incorrect.** "Designate" means to name or appoint; naming small companies does not explain how connecting them to knowledgeable investors would help them thrive.
**Choice C is incorrect.** "Preclude" means to prevent or make impossible, which contradicts the sentence’s positive claim that the exchange helps companies thrive.
**Choice D is incorrect.** "Assess" means to evaluate; while assessment might be useful, it does not by itself produce the supportive outcome implied by "help those companies thrive."
**Faster approach:** Focus on the clause that follows ("help those companies thrive") and choose the verb that denotes encouraging growth—eliminate words that mean label, prevent, or merely evaluate.'),
  ('6a48d633-7c39-5882-9c19-2b4ef0ebdcd0', 2, null, '**Choice C is correct.** The passage contrasts the realist style’s focus on ordinary people and their imperfections with the romantic style’s tendency to exaggerate beauty and hide flaws; realism is presented as a response opposing those excesses. The verb "counteract" precisely expresses the idea of acting against or neutralizing the romantic style’s excesses, so it best completes the sentence.
**Choice A is incorrect.** "Understand" means to comprehend, but the passage indicates an active response to romantic excesses, not merely comprehension.
**Choice B is incorrect.** "Advance" means to promote or support, which contradicts the passage’s implication that realism reacted against romantic exaggeration.
**Choice D is incorrect.** "Accentuate" means to emphasize or highlight, which would align realism with rather than oppose the romantic style’s excesses.
**Faster approach:** Look for the contrast words (e.g., "can thus be seen as an effort to" and the negative description of romantic excesses) and pick the answer that means "oppose" or "neutralize."'),
  ('43216bc3-6af5-5a7d-9f05-c3fa38678457', 0, null, '**Choice A is correct.** The sentence says the speed difference exists because of a particular fact about flight versus swimming; saying it is "a consequence of the fact that..." precisely expresses that causal relationship. The noun "consequence" with the preposition "of" correctly links the difference to its cause.
**Choice B is incorrect.** "An explanation of the fact that" would mean the difference explains the fact, which reverses the intended causal relationship; the passage intends the fact to explain the speed difference, not the other way around.
**Choice C is incorrect.** "A repudiation of the fact that" would mean the difference rejects the fact, which makes no sense in context because the sentence is presenting the fact as the reason for the difference.
**Choice D is incorrect.** "An objective of the fact that" is illogical: a fact cannot have an "objective" that explains a measured difference in speeds, and the phrase does not convey the causal link required.
**Faster approach:** Substitute each option into the sentence and check which yields a natural causal phrase; only "a consequence of" produces the intended cause‑effect meaning.'),
  ('46950318-a3ae-556c-8d62-23b2d8e09f85', 1, null, '**Choice B is correct.** The underlined sentence states a common perception—that Nixon is most famous for Watergate—and the very next sentence begins with "But Nixon’s legacy is complex," which directly challenges that simple perception by presenting other aspects of his record. The contrast word "But" signals that the passage will complicate or qualify the initial description.
**Choice A is incorrect.** The underlined sentence does not present an accomplishment; it presents a well-known scandal associated with Nixon, and the passage that follows complicates, rather than details, that significance.
**Choice C is incorrect.** The sentence is not a claim that the passage sets out to prove with supporting evidence; instead, it describes a widely held view that is then qualified by contrasting information.
**Choice D is incorrect.** The sentence does not compare achievements of multiple figures; it mentions Nixon and his associates but offers no comparison to three other historical figures.
**Faster approach:** Look for transition words (e.g., "but," "however") after the sentence; such contrast markers indicate the sentence is stating a common perception that will be challenged—so choose the answer that indicates a contrasting function.'),
  ('b759d5f4-bd19-5c1d-8642-bb29448416c3', 3, null, '**Choice D is correct.** The underlined sentence gives factual information about the Hibulb Cultural Center—what it does (presents Tulalip history and culture) and how it does it (using traditional knowledge to design exhibits). This is a straightforward, basic description of that particular tribal cultural center, which fits the passage’s comparison with other museums.
**Choice A is incorrect.** The sentence does not propose changes or improvements; it states how the center currently operates.
**Choice B is incorrect.** The sentence describes the center’s activities and audience but does not attempt to persuade or encourage attendance.
**Choice C is incorrect.** Although the passage later contrasts Indigenous-led centers with non-Indigenous-led museums, the underlined sentence itself describes one center rather than explaining how it differs from other tribal cultural centers.
**Faster approach:** Identify whether the sentence states facts, gives advice, or makes a comparison; a factual statement describing an institution signals a basic description answer choice.'),
  ('ebe72d19-de7c-56fe-9aea-d452b8a4e8e4', 3, null, '**Choice D is correct.** The underlined sentence points out that interactivity is central to video games and that a video-only presentation lacks that essential quality; this directly challenges MOMA’s decision to show some games only as videos and therefore partly undermines the museum’s exhibition approach.
**Choice A is incorrect.** The sentence does identify interactivity as a feature of video games, but it does not focus on a contrast between many games and specific games in the exhibit; its point is about the museum’s practice, not simply noting a feature missing from some games.
**Choice B is incorrect.** The sentence expresses the author’s claim about video games'' nature; it does not indicate that MOMA shares or accepts this claim.
**Choice C is incorrect.** The sentence is not describing a misconception; rather, it asserts a principle (inherent interactivity) that the author uses to critique MOMA’s choice, not to label MOMA’s view as a mistaken belief.
**Faster approach:** Identify whether the sentence supports or contradicts the author’s main point about the museum’s practice; if it undermines the museum’s action, choose the answer that frames it as a critique of the exhibition approach.'),
  ('37f8361f-4745-5ac5-82b9-01f8c858043a', 0, null, '**Choice A is correct.** The passage explicitly states that in O''odham "gogs" means "a dog" and "gogogs" refers to several dogs, and it explains that the element "go" in "gogs" gets repeated in "gogogs," which is an example of reduplication.
**Choice B is incorrect.** The passage gives a clear equivalent in English for both words: "gogs" = "a dog" and "gogogs" = "several dogs."
**Choice C is incorrect.** The passage says there are many examples of this type of reduplication in O''odham, so "gogogs" is not the only word that uses it.
**Choice D is incorrect.** "Gogogs" is said to refer specifically to several dogs, not to be identical in meaning to several other words.
**Faster approach:** Look for the sentence that defines the specific word—the explicit definition usually identifies the exact point being asked about.'),
  ('54c86ddd-6065-5abf-8a0a-dc25eb6f4ae3', 1, null, '**Choice B is correct.** The passage contrasts two critical perspectives about the novels'' structures: some critics "have found fault with the abrupt endings" while "other critics... argue" the books should be viewed as a single long work. The main purpose is to report these differing critical views about the efficacy of the series'' structural approach.
**Choice A is incorrect.** The passage does not claim that O''Brian’s structure makes Master and Commander especially intricate; it only describes critics'' reactions to the endings and to viewing the series as one long work.
**Choice C is incorrect.** The passage mentions The Forsyte Saga only as a comparison for viewing the series as a multivolume work, not as a claim about literary renown or critics arguing for comparable status.
**Choice D is incorrect.** Nowhere does the passage say critics find the novels "remarkably entertaining" despite structural flaws; it focuses solely on conflicting judgments about the series'' structural form.
**Faster approach:** Identify the topic (critics'' views) and the contrast words ("some... other critics") to eliminate choices that introduce unsupported details.'),
  ('04ae6d34-4bca-516c-aae9-762d6a0e3d9d', 1, null, '**Choice B is correct.** The sentence explicitly compares the father’s care for the lawn to careful personal grooming—"shaving this lawn as if it were a priest’s chin"—and then details his regular, attentive work "all during the season" in the cool evenings, with the result that "the grass was strong and healthy." Those phrases directly support the claim that Crane depicts the father’s dedication and care for the lawn.
**Choice A is incorrect.** That quotation focuses on finding the broken flower and the father’s reaction to Jim, not on ongoing care and dedication to the lawn.
**Choice C is incorrect.** That line emphasizes momentary quiet and birdsong after the machine stops, not the father’s careful maintenance.
**Choice D is incorrect.** That description shows action during mowing but emphasizes Jim’s behavior and the mechanical motion of grass spinning, not sustained, devoted care.
**Faster approach:** Look for wording that describes repeated, careful action or an explicit comparison to careful grooming; eliminate lines that focus on a single moment or on other characters.'),
  ('9ae3eccd-55e0-5646-820b-fc87024472bf', 0, null, '**Choice A is correct.** The graph shows that the bar for the smaller area (the dark bar labeled in the figure —intended as the smaller city) is lower than the New York City bar in every year from 1990 to 2000, and the heights of both bars increase from 1990 to 2000, indicating that although the smaller area experienced fewer delay hours each year, delay increased in both places over the period.
**Choice B is incorrect.** Although at least one area does show less than 20 hours in some years, this statement is a weaker, less directly relevant description of the specific claim about both large and small areas experiencing increased congestion over time.
**Choice C is incorrect.** The New York City bar in 1992 is well above 20 hours on the graph, so the statement that it was less than 20 hours is false.
**Choice D is incorrect.** The graph shows the smaller-area bars are consistently lower than New York City’s bars throughout 1990–2000, so the smaller area did not have greater delay than New York City.
**Faster approach:** Compare bar heights for the large city and a smaller area in the first and last years to check (1) which is higher each year and (2) whether both heights increase from start to finish; this quickly verifies the trend and relative magnitudes for any similar bar-graph question.'),
  ('fcf7dcff-4667-54a0-b889-88304a7e8c97', 0, null, '**Choice A is correct.** Alegado and colleagues concluded that both A. ratkowskyi and A. boritolerans might have played a role in the development of multicellularity; the most direct evidence for that conclusion would be if both Bowman and Ahmed observed that exposure to those bacteria caused S. rosetta to form colonies. Choice A states exactly that both researchers found colony formation after bacterial exposure, which directly supports the claim that those bacteria could have influenced multicellularity.
**Choice B is incorrect.** If only Bowman observed colony formation but Ahmed did not, the evidence would support a role for only one of the bacteria, not both.
**Choice C is incorrect.** If only Ahmed observed colony formation, that again supports only one bacterial species rather than both.
**Choice D is incorrect.** If neither found colony formation, there would be no direct evidence that those bacteria influenced colony formation in S. rosetta.
**Faster approach:** For questions about “both” or “each,” immediately eliminate choices that report results for only one or neither study and pick the choice that affirms both studies showed the effect.'),
  ('76562491-5202-5368-b61e-ee2ad072658d', 3, null, '**Choice D is correct.** Alegado and colleagues conclude that neither V. fischeri nor B. fragilis likely played a significant role in the evolution of multicellularity. The most direct evidence supporting that conclusion would be a finding that exposure to neither bacterium causes S. rosetta to form colonies—i.e., that these bacteria do not induce the colony-forming behavior thought relevant to multicellular development.
**Choice A is incorrect.** If S. rosetta formed colonies in response to both bacteria, that would suggest those bacteria could influence colony formation and therefore might have played a role, which contradicts the authors’ conclusion.
**Choice B is incorrect.** If only V. fischeri induced colony formation, that would implicate V. fischeri (even if not B. fragilis), so it would not support the claim that neither bacterium played a significant role.
**Choice C is incorrect.** Similarly, if only B. fragilis induced colonies, that would implicate B. fragilis and thus would not support the conclusion that neither bacterium was significant.
**Faster approach:** For evidence questions, translate the authors’ conclusion into a direct prediction (here: “no effect from either bacterium”) and choose the answer that matches that prediction exactly.'),
  ('3e7612ca-f0e8-5f1c-971b-d7d14006c813', 3, null, '**Choice D is correct.** The passage states that species with narrow geographical ranges tend to be more genetically homogeneous than species with extensive ranges. If M. anniana spreads beyond Tamaulipas, its geographical range would increase, and—consistent with the cited finding—the simulation would show a decrease in its genetic homogeneity over time.
**Choice A is incorrect.** The passage predicts changes in genetic homogeneity for the spreading species, not an increase in homogeneity of other Mammillaria species in neighboring states.
**Choice B is incorrect.** Nothing in the passage implies that other species would become more common in Tamaulipas as a result of M. anniana spreading.
**Choice C is incorrect.** The passage concerns genetic variation from range expansion, not predictions about future survivability of other species in Tamaulipas.
**Faster approach:** Translate the general finding into a simple conditional: "range increases → homogeneity decreases," then apply it to the species in the question to pick the matching choice.'),
  ('74e83b8b-8cdd-5615-84b4-508b0e4d6d49', 1, null, '**Choice B is correct.** The sentence requires a simple present finite verb to agree with the singular noun "textbook." "Raymond Chang’s textbook discusses this concept in detail" is grammatically correct and conveys that the book treats the concept in detail as a general fact.
**Choice A is incorrect.** "Discussing" is a present participle and would need an auxiliary or different structure (e.g., "...is discussing") to form a complete clause; as written it leaves the clause ungrammatical.
**Choice C is incorrect.** "To discuss" is an infinitive and does not fit here because it would require a different construction (for example, "Raymond Chang’s textbook aims to discuss...") to be grammatical.
**Choice D is incorrect.** "Having discussed" is a perfect participle that implies a preceding action and cannot stand as the main verb of the clause; it makes the sentence fragmentary.
**Faster approach:** Check subject–verb agreement and verb form: for a noun like "textbook," expect a simple present verb (adds -s for third-person singular), so choose the finite verb form that matches.'),
  ('2adcef42-c8b4-505b-8e43-19ecd4c4f16f', 2, null, '**Choice C is correct.** The sentence makes a general statement about what an emulsifier does, so the simple present tense is required. "Serves" correctly matches the present-tense main clause "An emulsifier is a type of compound" and expresses a habitual or defining function: an emulsifier serves to stabilize an emulsion.
**Choice A is incorrect.** "Served" is past tense and would imply the emulsifier no longer performs that function, which contradicts the general present-tense description in the sentence.
**Choice B is incorrect.** "Had served" is past perfect and implies a completed action before some other past event; there is no past context in the sentence to justify that tense.
**Choice D is incorrect.** "Was serving" is past progressive, suggesting an ongoing past action, which does not fit the general, timeless characterization required here.
**Faster approach:** For general truths or definitions, always use the simple present tense; pick the present-tense verb form.'),
  ('e806d65f-1f93-504f-8853-a8f6a8e64761', 0, null, '**Choice A is correct.** A colon correctly introduces a specific example or explanation of the general term that comes before it: "an important list: the Hawai''i Register of Historic Places." The clause before the colon is independent and the phrase after the colon names the list, so the colon use conforms to standard English.
**Choice B is incorrect.** Putting a period there would create a sentence fragment: "The Hawai''i Register of Historic Places." would be a fragment lacking a verb and would break the sentence awkwardly.
**Choice C is incorrect.** A semicolon must join two independent clauses; "the Hawai''i Register of Historic Places" is not an independent clause, so a semicolon is not appropriate.
**Choice D is incorrect.** Dropping punctuation ("list the Hawai''i Register…") creates an ungrammatical run-on noun phrase; a marker (such as a colon) is needed to introduce the specific list name.
**Faster approach:** Look for a punctuation mark that properly introduces a specific example or restatement of a preceding general term — a colon is the standard choice.'),
  ('a6ad3f61-7f81-59da-9970-a3e3f53f029a', 1, null, '**Choice B is correct.** A semicolon is needed to join two closely related independent clauses without a coordinating conjunction. The first clause ends with "visiting the guide’s recommended hotels and restaurants;" and the second clause, "as it grew in scope and influence, the guide had its modest French eateries replaced...," is a complete clause that provides a result or development. The semicolon cleanly separates the two clauses while maintaining their close relationship.
**Choice A is incorrect.** Leaving no punctuation between "restaurants" and "as" would create a run-on or fused sentence, making the sentence grammatically incorrect.
**Choice C is incorrect.** Adding "and" would force a coordination that makes the sentence awkward and ungrammatical because the second element is an independent clause introduced by "as," not a parallel noun or phrase.
**Choice D is incorrect.** A comma would create a comma splice by improperly joining two independent clauses, which is not acceptable in standard written English.
**Faster approach:** When a sentence has two independent clauses with no coordinating conjunction, choose a semicolon; if a subordinate clause begins the second part, a semicolon often separates the clauses cleanly.'),
  ('412c8458-579d-56a1-8571-f89915692591', 1, null, '**Choice B is correct.** The phrase needs to function as the subject of the verb "integrate," so it should read as an essential noun phrase without internal commas: "behavioral economists Laura Gee and Muriel Niederle integrate..." The plural noun phrase correctly matches the plural verb "integrate."
**Choice A is incorrect.** The comma after "Niederle" would separate the subject from the verb and create an incorrect break before "integrate," disrupting sentence flow and grammar.
**Choice C is incorrect.** The comma before "and Muriel Niederle" incorrectly separates two coordinated names; no comma is needed between two items joined by "and."
**Choice D is incorrect.** The comma after "economists" wrongly sets off an essential appositive; the names are essential to specify which economists and should not be bracketed by commas.
**Faster approach:** For subjects naming two people, choose the form with no internal commas (no unnecessary parenthetical punctuation) so the noun phrase directly precedes the verb.'),
  ('aa92079b-c811-5f0a-9a6c-998df0d7bfd1', 0, null, '**Choice A is correct.** The first sentence notes a recent expansion in 2020, and the second sentence asserts that further expansions will likely be needed; "Still," signals that, despite the recent work, additional expansions are expected. The transition preserves continuity and acknowledges a contrast in time or sufficiency (recent action vs. future need), so it fits logically and stylistically.
**Choice B is incorrect.** "By contrast," would introduce a direct opposition between the two statements, but the second sentence does not contradict the first; it rather complements it by noting continued need.
**Choice C is incorrect.** "For example," would introduce a specific instance illustrating a previous point, but the second sentence is not an example of the expansion; it’s a conclusion about future needs.
**Choice D is incorrect.** "Instead," implies an alternative action replacing the previous one, which is not the relationship here because the second sentence does not propose a substitute for the 2020 expansion.
**Faster approach:** Look for the logical relation (continuation, contrast, example, or substitution) between sentences; match the transition that expresses that relation—here, a concessive continuation, so choose "Still."'),
  ('83867587-4f11-5328-8b64-bd5c4ed522f9', 0, null, '**Choice A is correct.** The sentence before the blank emphasizes Tang’s modest, even casual motivation for creating the site, so the next clause that presents the site as an "essential resource" signals a contrast. "Nevertheless," is the transition that expresses contrast between his low ambitions and the site’s important outcome.
**Choice B is incorrect.** "Therefore," indicates a logical result of the prior statement, but the passage shows an unexpected contrast (modest ambition vs. important outcome), not a direct consequence.
**Choice C is incorrect.** "Furthermore," adds information in the same direction as the previous clause; here the sentence shifts to a contrasting outcome, so an additive transition is inappropriate.
**Choice D is incorrect.** "Next," signals sequence or chronology, but the passage needs a contrastive transition rather than a temporal one.
**Faster approach:** Spot whether the second clause contrasts with or follows from the first; if it contrasts, pick a contrast word like "However" or "Nevertheless,"; if it follows, pick "Therefore" or "As a result."'),
  ('936463e5-3d4f-52b2-a42a-7a411f0bd081', 0, null, '**Choice A is correct.** The sentence contrasts what Chaucer did not write (Modern English) with what he did write (Middle English), so a contrasting transition like "rather" fits best: "Chaucer didn’t write in Modern English; rather, he wrote in what we now call Middle English..." This preserves the intended opposition between the two clauses.
**Choice B is incorrect.** "As a result" indicates cause and effect, which doesn’t match the contrast between types of English in the sentence.
**Choice C is incorrect.** "Similarly" indicates similarity between two items, but the sentence is pointing out a difference (not Modern English vs. Middle English), so this is the wrong relationship.
**Choice D is incorrect.** "Finally" suggests a concluding idea in a sequence, which is not the intended function here; the sentence needs a contrast, not a conclusion.
**Faster approach:** Look for signal words that reveal the relationship between clauses (here "didn’t" signals contrast). Immediately select a contrasting transition such as "rather" or "instead."'),
  ('09be0928-3a4c-5a3a-8ec6-89b7c662e501', 1, null, '**Choice B is correct.** It gives specific, relevant evidence from the notes: it cites the amount of vitamin C in blueberries (10 mg per 100 g) and the amount in kale (120 mg per 100 g) and explicitly uses those numbers to support the claim that kale is a better source. The numerical comparison directly justifies the conclusion.
**Choice A is incorrect.** Although it notes that both contain ascorbic acid and that humans cannot make it, it does not provide the comparative evidence (the amounts per 100 g) needed to support the claim that kale is a better source.
**Choice C is incorrect.** It merely restates the claim that kale is a better source without citing any of the specific information (the mg per 100 g) from the notes to support that claim.
**Choice D is incorrect.** It explains why vitamin C is necessary in the diet but does not compare kale and blueberries or provide evidence that kale is a better source.
**Faster approach:** For questions asking which choice best supports a comparative claim, look for the option that includes the relevant quantitative comparison (the specific numbers) rather than general statements.'),
  ('8326192d-a21c-5b45-a359-f5be100c1414', 3, null, '**Choice D is correct.** The notes state that apatite is 5, calcite is 3, and topaz is 8 on the Mohs scale and that larger numbers are harder and can leave visible scratches on smaller numbers. Saying apatite (5) is harder than calcite (3) but softer than topaz (8) directly and accurately uses those facts to describe apatite’s hardness relative to the other minerals.
**Choice A is incorrect.** It compares topaz and calcite but says nothing about apatite, so it doesn’t explain how hard apatite is relative to other minerals.
**Choice B is incorrect.** While true that the three can be ordered by their ability to scratch, this choice is vague and does not state where apatite falls in that order.
**Choice C is incorrect.** Although topaz (8) can scratch apatite (5) and calcite (3), this choice focuses on topaz’s ability rather than explicitly stating apatite’s hardness relative to the others.
**Faster approach:** Compare the Mohs numbers directly—higher number = harder—so state where the target mineral’s number falls relative to the others’ numbers.'),
  ('cbeef642-b587-5eec-a788-3f78935d78ad', 1, null, '**Choice B is correct.** The notes state that Julie, or The New Heloise "consists primarily of letters" and that Absolutely Normal Chaos "consists primarily of journal entries," so this choice directly and accurately emphasizes the difference in document type between the two novels.
**Choice A is incorrect.** Although true, this choice merely notes that both authors wrote epistolary novels and does not emphasize a difference between the two works.
**Choice C is incorrect.** The notes do not support the general claim that "most" epistolary novels consist primarily of letters; they only give two specific examples, so the broad assertion is unsupported.
**Choice D is incorrect.** While it is true that the two novels show variety, this choice emphasizes similarity and variety rather than clearly highlighting the specific difference in document type between them.
**Faster approach:** For synthesis questions asking for a difference, skim the notes for contrasting details (words like "while," "consists primarily of," or explicit document types) and choose the option that directly pairs those specific contrasting facts.'),
  ('efccb86f-82ea-5870-9a6d-365208a999f4', 3, null, '**Choice D is correct.** The notes state that researchers catalogued fifteen native species and twenty-nine non-native species, so the researchers found more non-native seed species than native seed species; Choice D directly compares those numbers.
**Choice A is incorrect.** Although it correctly identifies which of the two named plants is native, it does not compare the counts of native and non-native species catalogued.
**Choice B is incorrect.** This restates the study context but does not compare the number of native and non-native species catalogued.
**Choice C is incorrect.** This combines two facts about bird origins and the researchers'' conclusion but does not address the numerical comparison of species counts.
**Faster approach:** Locate the numeric counts in the notes (15 native, 29 non-native) and directly state which is larger.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

-- PeaklyTest Jun 2023 · Reading & Writing · Module 2
