insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('039ab9b9-9aa0-533e-afd6-53be186af227', '5e626d3c-b021-5e87-94e6-e2c976cfe3e2', 'Which choice completes the text with the most logical and precise word or phrase?', '["reciprocate", "annotate", "abandon", "equalize"]'::jsonb, 1, 'Whether the reign of a French monarch such as Louis VII or Henry V was historically consequential or relatively uneventful, its trajectory was shaped by questions of legitimacy and therefore cannot be understood without a corollary understanding of the characteristics without which the monarch would have been forced to _____ the throne.'),
  ('b763039f-f0ba-53fb-8cca-7f4f352251ed', '5e626d3c-b021-5e87-94e6-e2c976cfe3e2', 'Which choice completes the text with the most logical and precise word or phrase?', '["required", "remembered", "achieved", "avoided"]'::jsonb, 2, 'With his widely celebrated portraits of poet Seamus Heaney, molecular biologist Struther Arnott, and other prominent figures in different fields, British painter Peter Edwards has _____ substantial prestige as an artist.'),
  ('b7fcf0e2-9690-58f6-ac61-856189ad4afb', '5e626d3c-b021-5e87-94e6-e2c976cfe3e2', 'Which choice completes the text with the most logical and precise word or phrase?', '["eccentric", "meager", "conventional", "random"]'::jsonb, 3, 'Though many _____ studies of the effect of altitude on blood chemistry focus on people who live above sea level, researchers Suleiman A. Al-Sweedan and Moath Alhaj recently chose the novel path of focusing on people who live below sea level, in locations such as the California towns of Salton City and Coachella.'),
  ('f0ad3c9d-4e54-5024-a68b-b6ff289a374c', '5e626d3c-b021-5e87-94e6-e2c976cfe3e2', 'As used in the text, what does the word "deep" most nearly mean?', '["Tough", "Hideous", "Complicated", "Intense"]'::jsonb, 4, 'The following text is adapted from William Wordsworth’s 1798 poem "Lines Written a Few Miles above Tintern Abbey."

Once again
Do I behold these steep and lofty cliffs,
Which on a wild secluded scene impress
Thoughts of more <u>deep</u> seclusion; and connect
The landscape with the quiet of the sky.'),
  ('742c8e17-a34f-5412-99de-9a8ca3adf417', '5e626d3c-b021-5e87-94e6-e2c976cfe3e2', 'Which choice completes the text with the most logical and precise word or phrase?', '["irresolvable", "self-contradictory", "imperative", "unavoidable"]'::jsonb, 5, 'The Caves of Gargas paintings—stencils of human hands found in what is now France and dating from around 27,000 years ago—are thought of as art today, but the question of whether the people of the time understood the paintings as something akin to art in our modern sense or in some other way entirely is _____; we will never be able to answer it.'),
  ('dd4f8fb9-ea60-5131-a928-7527511a2b99', '5e626d3c-b021-5e87-94e6-e2c976cfe3e2', 'Which choice best states the main purpose of the text?', '["To discuss two writers who blend traditional Indigenous stories with popular genres", "To urge younger Indigenous authors to avoid writing in popular genres", "To argue that traditional Indigenous stories are more memorable than most novels are", "To explain why one Indigenous author has achieved more success than another has"]'::jsonb, 6, 'Eden Robinson is a novelist and a member of the Haisla Nation in western Canada. Critics and fellow writers have praised her work for combining traditional Haisla stories with popular genres of literature, such as fantasy and mystery fiction. But Robinson is not the only Indigenous writer to blend traditional stories with popular literature. In the 2019 novel Empire of Wild, Cherie Dimaline successfully blended the oral storytelling tradition of her people, the Metis, with horror fiction.'),
  ('09296db4-626b-5358-9b06-bfed369ed939', '5e626d3c-b021-5e87-94e6-e2c976cfe3e2', 'Based on the texts, how would the author of Text 2 most likely respond to the claim in the underline sentence of Text 1', '["By arguing that people tend to disagree when identifying genre classifications for music", "By suggesting that the concept of genre may become more useful for music listeners", "By criticizing previous research into automated music genre classification for favoring specific genre categories", "By asserting that it may be possible to improve automated classification systems"]'::jsonb, 7, '**Text 1**

<u>Attempts to automate classification of music into genres have not been very successful, and we may</u> <u>be at the limit of what is technologically possible.</u> But it’s not clear that this is a worthwhile pursuit in any case--as Jin Ha Lee and An h Thu Nguyen argue in their study of the South Korean band BTS, relationships between pieces of music may be best understood with concepts other than genre.

**Text 2**

Tango is a genre of music originally from Argentina and Uruguay that shares some harmonic and rhythmic similarities with the pagode genre. Automated genre classification systems typically struggle to draw distinctions in situations like this, but Yandre Costa and colleagues solved that problem by converting sound to images and having computers compare features of those images, an approach that demonstrates how much innovation is possible in this field.'),
  ('b92b2f30-84d9-560e-ba71-fb750548154d', '5e626d3c-b021-5e87-94e6-e2c976cfe3e2', 'Based on the text, what does the narrator mainly remember about the times when his mother chanted to him?', '["That he liked the characters in the stories his mother made up while chanting.", "That his mother had music playing in the background while she chanted.", "That his mother didn’t usually chant at night.", "That he found the sound of his mother’s chanting to be calming."]'::jsonb, 8, 'The following text is adapted from Adib Khorram’s 2018 novel Darius the Great Is Not Okay. Darius, a teenager from the United States, is visiting his family members in Iran.
I dozed and floated on the clouds of Farsi that blew my way from the front seat of Dayi [Uncle] Jamsheed’s SUV.
It reminded me of when I was little, and Mom chanted to me in Farsi every night before bedtime. It’s hard to describe Farsi chanting: the way Mom drew her voice out like the notes of a cello as she recited poems by Rumi or Hafez. I didn’t know what they meant, but that didn’t matter. It was quiet and soothing.

©2018 by Adib Khorram'),
  ('1b6faf4a-2994-5ed8-bbe1-40b58d24ed54', '5e626d3c-b021-5e87-94e6-e2c976cfe3e2', 'Which choice best states the main idea of the text?', '["Researchers have long known that horses and barn owls can see in 3D.", "Cuttlefish are surprisingly similar in structure to octopuses and squid.", "Contrary to what many researchers had assumed, cuttlefish may be able to see in 3D.", "The ability to see in 3D allows many animals to interact with one another."]'::jsonb, 9, 'Horses and barn owls can see in three dimensions (3D), which helps them perceive distance and depth. Octopuses and squid are thought to lack 3D vision. Many researchers once thought the same about cuttlefish, but Trevor Wardill and his team wanted to test whether this assumption was true. The team studied how cuttlefish wearing 3D glasses reacted to 3D images of shrimp (a favorite prey) projected on a tank wall. Cuttlefish changed their striking position to match the 3D images, suggesting that their vision is more like that of horses and barn owls than that of octopuses or squid.'),
  ('6479f5f5-5072-556c-96b2-7db8abb136b6', '5e626d3c-b021-5e87-94e6-e2c976cfe3e2', 'Which choice most effectively uses data from the table to complete the statement?', '["Acropora anthocercis.", "Cyphastrea hexasepta.", "Agaricia fragilis.", "Heliofungia fralinae."]'::jsonb, 10, '**Minimum and Maximum Depths of Stony Coral Species in Caribbean and Indo-Pacific Waters**

| Species | Minimum depth (meters) | Maximum depth (meters) | Range (meters) |
| Acropora anthocercis | 5 | 10 | 5 |
| Cyphastrea hexasepta | 8 | 25 | 17 |
| Agaricia fragilis | 10 | 102 | 92 |
| Heliofungia fralinae | 3 | 27 | 24 |

The table is from a 2018 study in which Luiz Rocha and colleagues examined the ranges of depths at which certain stony coral species have been found in Caribbean and Indo-Pacific waters. Among the corals in the table, the species with the greatest range between minimum and maximum depths is _____'),
  ('69cf1697-7407-5b7c-85f1-2fffe4e52131', '5e626d3c-b021-5e87-94e6-e2c976cfe3e2', 'Which quotation from a translation of The Underdogs most effectively illustrates the claim?', '["\"The sierra is clad in gala colors. Over its inaccessible peaks the opalescent fog settles like a snowy veil on the forehead of a bride.\"", "\"All day long [the soldiers] rode through the canyon, up and down the steep, round hills, dirty and bald as a man’s head, hill after hill in endless succession.\"", "\"Then, hurriedly, [the soldiers] took the Juchipila canyon northward, without halting to rest until nightfall.\"", "\"The sun, beating down upon [the soldiers], dulled their minds and bodies and presently they were silent.\""]'::jsonb, 11, 'The Underdogs is a 1915 novel by Mariano Azuela, originally written in Spanish. In the novel, a group of soldiers travel through a canyon, where their collective mood becomes strongly affected by the strenuous conditions of their journey: ______'),
  ('bb79d0c5-5269-54a0-98d6-31126cafe77a', '5e626d3c-b021-5e87-94e6-e2c976cfe3e2', 'Which choice most effectively uses data from the table to complete the example?', '["average power generated annually by the Great Falls plant is higher than that generated by any of the run-of-river plants in the table.", "Scanlon plant, which is a run-of-river plant, has more generators than any of the other plants in the table.", "run-of-river plant with the highest average annual power generation in the table generates more electricity than the peaking plant with the highest annual power generation in the table.", "average power generated annually by the Kansas River plant is higher than that generated by the Scanlon plant."]'::jsonb, 12, '**US Hydroelectric Power Plants, 2019**

| Plant | State | Mode | Average annual power generation (MWh/yr) | Water Source |
| Scanlon Plant | Minnesota | Run-of- river | 7,511 | St. Louis River |
| Kansas River Plant | Kansas | Run-of- river | 15,345 | Kansas River |
| Squa Pan Hydro | Maine | Peaking | 881 | Squa Pan Stream |
| Great Falls | Tennessee | Peaking | 124,392 | Caney Fork River |

A run-of-river hydroelectric power plant, as the name suggests, uses the natural flow of a water source to generate electricity but is unable to start or stop that flow through its generators. In contrast, a peaking hydroelectric power plant (used when demand for electricity peaks) controls the flow of water through its generators: starting flow when demand is high enough, stopping it when demand is too low, and otherwise regulating it to keep pace with changing electricity needs. Although peaking plants do not typically operate continuously as run-of-river plants do, peaking plants can generate more megawatt-hours of power per year (MWh/yr) than some run-of-river plants. For example, the _______'),
  ('749d72c7-46dd-5dbd-b874-2742ef1d4b49', '5e626d3c-b021-5e87-94e6-e2c976cfe3e2', 'Which quotation from an interview with a costume designer would most effectively support the student’s claim?', '["\"I tend to pay careful attention to a character’s accessories like gloves, hats, and jackets. These elements help communicate information about how this person would have fit into society at the time.\"", "\"I aim to create a clear sense of the character and the world they inhabit. Sometimes this means adhering to the historical period’s style, but frequently, as in stagings of A Midsummer Night’s Dream, some flexibility is required to communicate an idea to the audience.\"", "\"Costumes must always reflect the correct historical period. Too often, I’ve seen costumes that borrow from a wide span of periods, resulting in a production with a confusing visual style.\"", "\"In the 1980s I was costuming for a production of A Midsummer Night’s Dream. Even though I focused on using the correct materials and techniques for the play’s period in history, when I look back I can clearly see the influence of 1980s fashion in my designs.\""]'::jsonb, 13, 'The 2000 production of The Green Bird was the first Broadway show for which Constance Hoffman was credited as a costume designer. Hoffman was among the Broadway costume designers interviewed by Sara Jablon-Roberts and Eulanda A. Sanders for their study of historical accuracy in costume design for shows with a historical setting. They found that even designers who value historical accuracy will often include contemporary design elements that don’t fit with the historical period. In a research paper about theatrical costume design, a student argues that costume designers for modern productions of Shakespeare’s A Midsummer Night’s Dream (set in ancient Greece) sometimes include such elements unintentionally.'),
  ('ebd91d54-5e1b-5c52-a234-a4084c5751e5', '5e626d3c-b021-5e87-94e6-e2c976cfe3e2', 'Which choice most logically completes the text?', '["a group of researchers had an extensive discussion on Twitter about the design of tractor engines.", "most of the papers in the Scopus and Web of Science databases do not discuss automotive engines or social media websites.", "the word \"twitter\" may not always refer to a social media website, but to other subjects such as noises made by machines.", "academics who are active on social networks are likely to announce their recent publications on Twitter."]'::jsonb, 14, 'In order to identify research trends, Shirley Ann Williams et al., reviewed a collection of studies of the social media website Twitter, such as the 2011 paper by Celik et al., titled "Learning Semantic Relationships between Entities in Twitter." Williams’s team searched for the term "Twitter" on the Scopus and Web of Science databases and found that, though most papers returned by the search did in fact focus on the social media platform, a few discussed unrelated subjects such as sounds made by tractor engines. One reasonable explanation for this result is that it occurred because _____'),
  ('51a0157a-03c9-5840-b29a-6c8f16f00007', '5e626d3c-b021-5e87-94e6-e2c976cfe3e2', 'Which choice most logically completes the text?', '["the mercury levels reported in Noh and colleagues'' study were much higher than those reported in the study by Berndt and Bavin even though the dissolved organic carbon levels reported in the two studies were approximately the same.", "Berndt and Bavin may have inadvertently measured a different characteristic of bodies of fresh water than their levels of dissolved organic carbon and mercury.", "the relationship between dissolved organic carbon and mercury reported by Berndt and Bavin reflects conditions that are characteristic of certain kinds of ecosystems in North America rather than universal conditions.", "most of the studies conducted in North America have measured dissolved organic carbon and mercury levels at a higher level of precision than was the case in Noh and colleagues'' study."]'::jsonb, 15, 'In a 2012 study in the United States, Michael E. Berndt and Travis K. Bavin found a positive association between levels of dissolved organic carbon and mercury in bodies of fresh water. Many other studies have yielded similar results, suggesting to some scientists that this association is true for all bodies of fresh water. But much of that research has been conducted at broadly similar sites in North America, and when Seam Noh and colleagues examined bodies of fresh water in South Korea, they found a negative association between dissolved organic carbon levels and mercury levels. If similar findings emerge from other locations outside North America, that could suggest that _____'),
  ('db46dbd0-d0c9-59c3-95ed-866df7b3c0af', '5e626d3c-b021-5e87-94e6-e2c976cfe3e2', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["cut, bent, and,", "cut, bent, and", "cut, bent; and", "cut bent, and"]'::jsonb, 16, 'In the thought-provoking 2010 exhibition Relative Pelican at the Stux Gallery in New York, Sokari Douglas Camp presented sculptures that had been _____ welded from recycled metal materials, such as oil drums. In doing so, the London-based Nigerian sculptor challenged viewers to imagine new uses and futures for the material wastes of the past.'),
  ('0996db78-9b8a-5d5e-8f84-056c4e03bb76', '5e626d3c-b021-5e87-94e6-e2c976cfe3e2', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["by", "by—", "by,", "by:"]'::jsonb, 17, 'In Puerto Rico, it’s not unusual for a city or town to be known _____ a nickname that corresponds to one of its notable features, like landscape, climate, famous residents, or chief exports. For example, the Puerto Rican municipality of Hatillo has also been called "the Land of Green Fields," a nickname that alludes to what the area is well known for: the lush greenery that surrounds it.'),
  ('dfb76a42-d26b-5a7f-9928-c9bc404a13c1', '5e626d3c-b021-5e87-94e6-e2c976cfe3e2', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["working", "was working", "to work", "to have worked"]'::jsonb, 18, 'In 2021, Sarah McAnulty _____ as a biologist at the University of Connecticut, studying squids.'),
  ('de772061-8255-5df8-b538-4ed3ea74f4d2', '5e626d3c-b021-5e87-94e6-e2c976cfe3e2', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["were", "were being", "was", "have been"]'::jsonb, 19, 'The word "robot" _____ first used in the 1920 play R. U. R. by Czech author Karel Capek.'),
  ('5045b925-100b-5cf2-8bf2-27d4d00ab2ee', '5e626d3c-b021-5e87-94e6-e2c976cfe3e2', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["have been ranking", "was ranked", "were ranked", "are ranking"]'::jsonb, 20, 'In the spring of 1964, it was hard to go anywhere without hearing the song "Cotton Candy" by the Sylvers. As of April 11, the song had spent thirteen straight weeks on the Billboard Hot 100 chart and _____ No. 1 on the list.'),
  ('9cb6dc40-84cd-5c26-9637-fbce0ae970ec', '5e626d3c-b021-5e87-94e6-e2c976cfe3e2', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["they cite", "cited", "citing", "has cited"]'::jsonb, 21, 'In 2000, the United States Congress designated a portion of Pennsylvania as the Lackawanna Valley National Heritage Area, _____ the region’s unique natural, cultural, and historical attributes.'),
  ('63fcb9f4-2afd-56fe-a420-7a4e6f33d39e', '5e626d3c-b021-5e87-94e6-e2c976cfe3e2', 'Which choice completes the text with the most logical transition?', '["Today,", "For instance,", "In other words,", "Thus,"]'::jsonb, 22, 'In 1940, scientists first isolated a sample of the steroid hormone androstenone, which they knew existed in animals—and, they assumed, only in animals. _____ scientists know that androstenone can also be found in chokecherry plants (Prunus virginiana), but this discovery didn’t occur until decades later.'),
  ('3ee051e8-b112-5a7f-8ca5-d0179b8b6b4c', '5e626d3c-b021-5e87-94e6-e2c976cfe3e2', 'Which choice completes the text with the most logical transition?', '["in addition,", "similarly,", "for instance,", "however,"]'::jsonb, 23, 'According to traditional classifications, each of William Shakespeare’s plays belongs to one of three distinct genres: comedy, history, or tragedy. The play Much Ado About Nothing (1598-99), ______ is classified as a comedy, whereas Richard II (1595) is classified as a history.'),
  ('f795e118-3a73-502a-8bb9-2d9881b07be9', '5e626d3c-b021-5e87-94e6-e2c976cfe3e2', 'Which choice completes the text with the most logical transition?', '["Still,", "Besides,", "Second,", "Fittingly,"]'::jsonb, 24, 'If you were to view the Ol Kokwe volcano in Kenya or the Asavyo volcano in Ethiopia from above, you might notice that their low profiles and gently sloping sides make each of them look a bit like a shield lying flat on the ground. _____ volcanologists classify volcanoes of this type as shield volcanoes.'),
  ('acc3e12e-ab7f-5c2e-9ab2-52c603433876', '5e626d3c-b021-5e87-94e6-e2c976cfe3e2', 'Which choice completes the text with the most logical transition?', '["Previously,", "Specifically,", "Likewise,", "Thus,"]'::jsonb, 25, 'Though its onboard laboratory allowed it to analyze rock samples on site, the 2011 Mars Curiosity rover was unable to preserve samples for future analysis. _____ when creating the 2020 Mars Perseverance rover, robotics mechanical engineer Arash Kalantari and other members of NASA’s Jet Propulsion Laboratory sought to implement a mechanism that could do exactly that.'),
  ('65db930f-275d-50e3-89b3-7c94b902c334', '5e626d3c-b021-5e87-94e6-e2c976cfe3e2', 'Which choice completes the text with the most logical transition?', '["therefore,", "to this end,", "however,", "in other words,"]'::jsonb, 26, 'Though the musical groups Los Palominos and Banda Los Recoditos are often categorized under the catchall "regional Mexican music" label, they each adhere to distinct musical traditions. The former works within the tejano tradition, which originated in mid-twentieth-century Texas and northern Mexico. The latter, _____ follows the banda tradition, with roots in mid-nineteenth-century southern and central Mexico.'),
  ('6dcf3c60-73a6-52ef-8019-29536acd5f20', '5e626d3c-b021-5e87-94e6-e2c976cfe3e2', 'Which choice completes the text with the most logical transition?', '["There,", "For instance,", "Regardless,", "Instead,"]'::jsonb, 27, 'Water from the aquifers of Alaska’s Susitna Glacier travels the 160 km length of the Skwentna River before flowing into the Yentna River and then reaching the mouth of the river system’s main stem, the Susitna River. _____ at the Susitna’s mouth, hundreds of kilometers from the source, the water empties into the Gulf of Alaska.')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('039ab9b9-9aa0-533e-afd6-53be186af227', 2, null, '**Choice C is correct.** The context says a monarch’s reign depends on certain characteristics and that without them the monarch would be forced to leave the throne. "Abandon" precisely means to give up or relinquish the throne, so it completes the sentence logically and concisely.
**Choice A is incorrect.** "Reciprocate" means to return a favor or response; it does not fit the idea of being forced off the throne.
**Choice B is incorrect.** "Annotate" means to add notes or commentary, which is unrelated to losing or leaving a position of power.
**Choice D is incorrect.** "Equalize" means to make equal; it does not convey being compelled to vacate the throne.
**Faster approach:** Use quick elimination by matching each option’s basic meaning to the required idea of "give up or leave the throne," which immediately narrows to "abandon."'),
  ('b763039f-f0ba-53fb-8cca-7f4f352251ed', 2, null, '**Choice C is correct.** The verb "achieved" naturally collocates with the noun "prestige," and it logically completes the sentence: by producing widely celebrated portraits, Edwards has attained or earned substantial prestige as an artist.
**Choice A is incorrect.** "Required" does not make sense here because one does not "require prestige" in this context; the sentence describes a result of Edwards’s work, not a necessity.
**Choice B is incorrect.** "Remembered" is about being recalled or commemorated, which does not convey the idea of gaining reputation or esteem conveyed by "prestige."
**Choice D is incorrect.** "Avoided" contradicts the sentence’s implication that his celebrated portraits produced a positive outcome; "avoided substantial prestige" is illogical here.
**Faster approach:** Use collocation checking—test which verbs commonly pair with "prestige."
"Achieve"/"gain" fits; the others do not—choose the matching verb immediately.'),
  ('b7fcf0e2-9690-58f6-ac61-856189ad4afb', 2, null, '**Choice C is correct.** The sentence contrasts the researchers'' novel approach with the typical approach. The word "conventional" means usual or commonly accepted, which fits the idea that most studies focus on people who live above sea level, so these researchers did something different by studying those below sea level.
**Choice A is incorrect.** "Eccentric" means odd or unconventional in behavior; while it implies difference, it describes people or behavior, not the usual character of the studies themselves, and it would suggest oddity rather than common practice.
**Choice B is incorrect.** "Meager" means small in amount or insufficient; that does not logically describe the studies in the context, since the passage refers to their focus, not their quantity or quality.
**Choice D is incorrect.** "Random" means lacking a specific pattern or plan; the passage implies a common, predictable focus (above sea level), not randomness, so this choice does not create the intended contrast with the researchers'' novel focus.
**Faster approach:** Look for a word that creates a contrast with "novel"—choose a word meaning "usual" or "typical" (i.e., "conventional").'),
  ('f0ad3c9d-4e54-5024-a68b-b6ff289a374c', 3, null, '**Choice D is correct.** In the phrase "deep seclusion," "deep" modifies the noun "seclusion" to intensify it; the poet means a serious, intense sense of being secluded. "Deep" here conveys a strong or profound quality, so "intense" is the best match.
**Choice A is incorrect.** "Tough" suggests difficulty or hardness, which does not fit the poet’s description of the quality of seclusion.
**Choice B is incorrect.** "Hideous" means ugly or horrifying; the context describes quiet, secluded cliffs, not something frightening or ugly.
**Choice C is incorrect.** "Complicated" suggests complexity or intricacy; the passage emphasizes the degree of seclusion, not that the seclusion is complex.
**Faster approach:** Substitute each answer into the phrase "deep seclusion" and choose the one that preserves the meaning ("intense seclusion" fits best), a quick context-based synonym check that works for vocabulary-in-context questions.'),
  ('742c8e17-a34f-5412-99de-9a8ca3adf417', 0, null, '**Choice A is correct.** The sentence ends with "we will never be able to answer it," which directly indicates that the question cannot be solved; "irresolvable" means "unable to be resolved," so it precisely completes the sentence. The wording matches both logically and stylistically.
**Choice B is incorrect.** "Self-contradictory" means containing conflicting statements; the sentence is about the impossibility of knowing an answer, not about the question contradicting itself.
**Choice C is incorrect.** "Imperative" means "necessary" or "urgent," which conflicts with the clause saying the question cannot be answered.
**Choice D is incorrect.** "Unavoidable" means "cannot be avoided," which is unrelated to the inability to answer the question; it reverses the intended meaning.
**Faster approach:** Spot the clause "we will never be able to answer it" and choose the option meaning "cannot be resolved" (irresolvable) without overanalyzing other choices.'),
  ('dd4f8fb9-ea60-5131-a928-7527511a2b99', 0, null, '**Choice A is correct.** The passage names two Indigenous novelists, Eden Robinson and Cherie Dimaline, and notes that each "blends traditional" stories of their peoples with popular genres (fantasy, mystery, horror). The central idea is comparing these two writers’ shared practice, which matches the statement in choice A.
**Choice B is incorrect.** Nothing in the passage urges younger authors or gives advice; it only describes what the two named writers do.
**Choice C is incorrect.** The passage does not claim traditional Indigenous stories are more memorable than novels; it only says these stories are combined with popular genres.
**Choice D is incorrect.** The passage does not compare the authors’ levels of success or explain why one has achieved more success than the other; it simply notes both have blended traditions with popular genres.
**Faster approach:** For main-purpose questions, identify the topic and repeated action (here, writers blending traditional stories with popular genres) and choose the answer that restates that main idea.'),
  ('09296db4-626b-5358-9b06-bfed369ed939', 3, null, '**Choice D is correct.** Text 2 describes a specific technical advance—converting sound to images and comparing image features—that "solved" a known classification difficulty and shows "how much innovation is possible in this field." That response directly contradicts the claim in Text 1 that automated classification "may be at the limit of what is technologically possible," by asserting improvement is possible.
**Choice A is incorrect.** Text 2 does not discuss disagreement among people identifying genres; it focuses on computational methods and innovation, not human disagreement.
**Choice B is incorrect.** Text 2 does not argue that genre will become more useful to listeners; it emphasizes technical advances in algorithmic classification rather than changes in listener usefulness of genre.
**Choice C is incorrect.** Text 2 does not criticize earlier research for favoring specific categories; instead it offers a new method that overcomes classification challenges, not a critique of categorical bias.
**Faster approach:** Look for a sentence that directly contradicts the underlined claim—here, Text 2’s statement that a new method "solved" classification problems clearly supports improvement, so choose the option asserting possible improvement.'),
  ('b92b2f30-84d9-560e-ba71-fb750548154d', 3, null, '**Choice D is correct.** The narrator explicitly says the chanting was "quiet and soothing" and that he "didn’t know what they meant, but that didn’t matter," which emphasizes that the calming sound, not the words or content, is what he remembers.
**Choice A is incorrect.** The passage states the narrator did not understand the words of the poems, so he could not be remembering characters in stories his mother made up.
**Choice B is incorrect.** There is no mention of music playing in the background; the calming quality is attributed to his mother’s voice and chanting style.
**Choice C is incorrect.** The passage indicates his mother chanted to him "every night before bedtime," so it contradicts the claim that she didn’t usually chant at night.
**Faster approach:** Look for direct wording that characterizes the memory (e.g., "quiet and soothing") and match that to the choice describing the narrator’s main impression.'),
  ('1b6faf4a-2994-5ed8-bbe1-40b58d24ed54', 2, null, '**Choice C is correct.** The passage explains that researchers previously assumed cuttlefish lacked 3D vision but then describes Wardill’s experiment showing cuttlefish wearing 3D glasses adjusted striking positions in response to 3D images, indicating they may perceive depth. This directly supports the claim that cuttlefish may be able to see in 3D contrary to prior assumptions.
**Choice A is incorrect.** While the passage mentions horses and barn owls can see in 3D, that is background information, not the main idea.
**Choice B is incorrect.** The passage contrasts cuttlefish with octopuses and squid regarding 3D vision rather than claiming structural similarity.
**Choice D is incorrect.** The passage focuses on cuttlefish vision and an experiment, not on how 3D vision enables interactions between animals generally.
**Faster approach:** Identify the passage’s problem and conclusion: note the prior assumption then the new experimental result—this contrast pinpoints the main idea quickly.'),
  ('6479f5f5-5072-556c-96b2-7db8abb136b6', 2, null, '**Choice C is correct.** The table lists each species'' range in the rightmost column; Agaricia fragilis has a range of $92$ meters, which is larger than the ranges given for the other species (5, 17, and 24 meters).
**Choice A is incorrect.** Acropora anthocercis has a range of $5$ meters, much smaller than Agaricia fragilis’s $92$ meters.
**Choice B is incorrect.** Cyphastrea hexasepta’s range is $17$ meters, which is not the greatest value in the table.
**Choice D is incorrect.** Heliofungia fralinae’s range is $24$ meters, also less than the $92$-meter range of Agaricia fragilis.
**Faster approach:** Directly read the "Range" column and choose the species with the largest numeric value; no calculation is needed if the table already provides ranges.'),
  ('69cf1697-7407-5b7c-85f1-2fffe4e52131', 3, null, '**Choice D is correct.** The claim says the soldiers'' collective mood is strongly affected by strenuous conditions; D explicitly links a physical stressor to a change in mood and behavior: “The sun, beating down upon [the soldiers], dulled their minds and bodies and presently they were silent.” That sentence states cause (strenuous heat) and effect (dulled minds, silence), directly supporting the claim about mood being affected.
**Choice A is incorrect.** A offers a vivid, positive description of the sierra’s appearance but does not show the soldiers’ mood or how conditions affect them.
**Choice B is incorrect.** B describes difficult terrain and fatigue (“dirty and bald… hill after hill”) but focuses on physical surroundings rather than the soldiers’ collective mood.
**Choice C is incorrect.** C reports their movement without rest, which implies exertion but does not describe any resultant change in mood or behavior.
**Faster approach:** Scan choices for explicit cause-and-effect language linking conditions to emotions or behavior; pick the option that names both the stressor and the psychological effect.'),
  ('bb79d0c5-5269-54a0-98d6-31126cafe77a', 0, null, '**Choice A is correct.** The table shows that the peaking Great Falls plant generates 124,392 MWh/yr, which is greater than the run-of-river Scanlon (7,511 MWh/yr) and Kansas River (15,345 MWh/yr) plants; thus it provides a clear example that a peaking plant can generate more annual power than some run-of-river plants.
**Choice B is incorrect.** The table gives no information about the number of generators at any plant, so this statement cannot be supported by the data.
**Choice C is incorrect.** It asserts that the highest run-of-river output exceeds the highest peaking output; the table shows the opposite (Great Falls peaking: 124,392 MWh/yr vs highest run-of-river 15,345 MWh/yr).
**Choice D is incorrect.** Although the Kansas River plant does generate more than Scanlon, this fact does not illustrate the intended contrast between peaking and run-of-river plants.
**Faster approach:** Scan the mode column to find a peaking plant, then compare its MWh/yr value to the run-of-river values—choose the option that states that numeric comparison.'),
  ('749d72c7-46dd-5dbd-b874-2742ef1d4b49', 3, null, '**Choice D is correct.** The student claims that designers sometimes include contemporary elements unintentionally; Choice D directly supports that claim by describing a designer who intended historical accuracy but later recognizes the influence of 1980s fashion on the designs. The phrasing "Even though I focused on... I can clearly see the influence of 1980s fashion" signals that the contemporary elements were not deliberately chosen to be anachronistic.
**Choice A is incorrect.** This quote emphasizes careful attention to historically appropriate accessories and implies deliberate, period-accurate choices rather than accidental contemporary influence.
**Choice B is incorrect.** Although it acknowledges flexibility in staging A Midsummer Night’s Dream, it frames such departures as deliberate communicative choices, not unintentional inclusions.
**Choice C is incorrect.** This statement insists costumes "must always reflect the correct historical period" and criticizes borrowing across periods, which contradicts the student’s claim about unintentional contemporary elements.
**Faster approach:** For evidence questions about unintended influence, scan for contrast markers (e.g., "even though," "despite") or admissions of hindsight; eliminate choices that describe deliberate stylistic decisions.'),
  ('ebd91d54-5e1b-5c52-a234-a4084c5751e5', 2, null, '**Choice C is correct.** The passage explains that most search results focused on the social media platform but a few discussed unrelated subjects such as sounds made by tractor engines; the most direct explanation is that the word “twitter” can have multiple meanings, including noises made by machines, so searching for the word picks up both senses.
**Choice A is incorrect.** If researchers had discussed tractor engines on Twitter, those discussions would be social-media content, not unrelated papers in databases, so this does not explain why database search results included papers about tractor-engine sounds.
**Choice B is incorrect.** This statement is too general and does not address why papers about tractor-engine sounds appear in a search for “Twitter”; it also conflicts with the passage’s claim that most returned papers did focus on the platform.
**Choice D is incorrect.** Announcements of publications on Twitter would produce social-media content related to academics, not academic papers about tractor-engine noises, so this does not account for the unrelated database results.
**Faster approach:** Look for the answer that directly accounts for the specific unexpected example given (tractor-engine sounds); for word-search issues, prefer choices pointing to multiple meanings of the search term.'),
  ('51a0157a-03c9-5840-b29a-6c8f16f00007', 2, null, '**Choice C is correct.** The passage notes that many studies (mostly in North America) found a positive association, while Noh’s study in South Korea found a negative one; if similar negative findings appear in other non-North American locations, that pattern would indicate the positive relationship is not universal but instead may reflect conditions specific to certain North American ecosystems.
**Choice A is incorrect.** The passage compares the direction of associations across studies, not absolute mercury magnitudes, so differences in reported levels do not explain the geographical pattern described.
**Choice B is incorrect.** There is no suggestion that Berndt and Bavin mismeasured variables; the issue is geographic generalizability, not measurement error.
**Choice D is incorrect.** The passage does not discuss measurement precision differences between regions; precision wouldn’t explain a systematic sign reversal of the association.
**Faster approach:** For inference questions about generality, ask whether counterexamples from other populations undermine a claimed universal relationship; if so, choose the answer that limits the claim to specific contexts.'),
  ('db46dbd0-d0c9-59c3-95ed-866df7b3c0af', 1, null, '**Choice B is correct.** The sentence requires a coordinated list of participial verbs modifying "sculptures": "cut, bent, and welded." Choice B supplies the commas and the conjunction correctly, producing the parallel phrase "had been cut, bent, and welded from recycled metal materials." This conforms to Standard English punctuation and parallel structure.
**Choice A is incorrect.** It inserts an extra comma after "and," yielding "cut, bent, and, welded," which is ungrammatical because a comma should not follow the coordinating conjunction in a simple list.
**Choice C is incorrect.** The semicolon before "and" breaks the simple series into two independent clauses, which is incorrect here; the items are not independent clauses and should be separated by commas.
**Choice D is incorrect.** It omits the comma after "cut," making the list nonparallel and harder to parse; standard lists require commas between items.
**Faster approach:** For list items that are verbs modifying the same noun, use commas between items and place "and" before the final item (i.e., serial comma) to create a smooth, parallel phrase such as "A, B, and C."'),
  ('0996db78-9b8a-5d5e-8f84-056c4e03bb76', 0, null, '**Choice A is correct.** The phrase "known by a nickname" is the standard idiom: the preposition "by" directly links "known" to the agent or label (the nickname) without any intervening punctuation. This makes the sentence grammatically smooth and precise: "...to be known by a nickname that corresponds..."
**Choice B is incorrect.** A dash (—) after "by" is unnecessary and disrupts the normal prepositional phrase; it creates an awkward break and is not required by the sentence structure.
**Choice C is incorrect.** A comma after "by" similarly interrupts the preposition and the noun phrase that follows; commas do not belong between a preposition and its object.
**Choice D is incorrect.** A colon after "by" is ungrammatical here because a colon introduces an independent clause, list, or explanation—not the direct object of a preposition.
**Faster approach:** Use the simplest, uninterrupted prepositional phrase—no punctuation between a preposition and its object—so choose the plain preposition "by."'),
  ('dfb76a42-d26b-5a7f-9928-c9bc404a13c1', 1, null, '**Choice B is correct.** The time phrase "In 2021" places the action in the past, so the verb must be in a past tense form; "was working" correctly provides a past progressive verb that indicates she held that position during 2021. The phrasing "studying squids" describes what she was doing while working, which fits with the progressive aspect.
**Choice A is incorrect.** "working" is a present participle and cannot stand alone as the main verb here; it would create a sentence fragment without an auxiliary (e.g., "was").
**Choice C is incorrect.** "to work" is an infinitive and does not match the past-time context introduced by "In 2021."
**Choice D is incorrect.** "to have worked" is a perfect infinitive and is ungrammatical here because the sentence requires a simple past or past progressive verb to agree with the time marker.
**Faster approach:** When a sentence begins with a specific past-time phrase (like "In 2021"), immediately pick a past-tense verb form; eliminate present participles and infinitives.'),
  ('de772061-8255-5df8-b538-4ed3ea74f4d2', 2, null, '**Choice C is correct.** The sentence describes a single past event: the first appearance of the word “robot” in a 1920 play. The singular subject “The word ‘robot’” requires a singular verb, and the passive voice is needed because the sentence emphasizes where the word was used (not who used it). The simple past passive form “was first used” correctly matches those requirements.
**Choice A is incorrect.** “Were” is plural and does not agree with the singular subject “The word ‘robot.’”
**Choice B is incorrect.** “Were being” is plural and creates an awkward progressive passive that doesn’t fit a one-time historical event.
**Choice D is incorrect.** “Have been” is present perfect and suggests relevance to the present; it also lacks the past passive marker and does not match the clear past time reference to 1920.
**Faster approach:** Identify the subject’s number (singular) and the time reference (past); choose a singular past-tense passive construction — “was” + past participle — every time for a one-time past passive event.'),
  ('5045b925-100b-5cf2-8bf2-27d4d00ab2ee', 1, null, '**Choice B is correct.** The surrounding context sets the action in the past (“In the spring of 1964,” “had spent”), so the clause should use a past tense form that fits with that time frame. “Was ranked” is simple past passive and correctly states the song’s position on the chart at that past time: “had spent thirteen straight weeks … and was ranked No. 1.”
**Choice A is incorrect.** “Have been ranking” is present perfect progressive and conflicts with the past time frame established by “In the spring of 1964” and “had spent.”
**Choice C is incorrect.** “Were ranked” uses a plural verb form that does not agree with the singular subject “the song.”
**Choice D is incorrect.** “Are ranking” is present tense and therefore inconsistent with the passage’s past setting.
**Faster approach:** Match verb tense to the time marker (here, a past date); eliminate any present-tense choices and any that disagree in number with the subject.'),
  ('9cb6dc40-84cd-5c26-9637-fbce0ae970ec', 2, null, '**Choice C is correct.** The sentence needs a word that links the act of designating to the reason for that designation; a present-participial phrase does this. "Citing the region’s unique natural, cultural, and historical attributes" explains why Congress made the designation, and the participle "citing" correctly modifies the entire main clause.
**Choice A is incorrect.** "They cite" is a finite verb phrase with a plural subject that has no clear antecedent and doesn’t grammatically attach to the main clause.
**Choice B is incorrect.** "Cited" is a past participle that would require a helping verb or produce a passive construction; it does not smoothly explain the reason for the designation here.
**Choice D is incorrect.** "Has cited" is present perfect and creates a separate clause that clashes with the past-tense main verb "designated."
**Faster approach:** For clauses that explain reason, scan for a gerund/participle ("-ing") that attaches to the main clause; such forms often signal cause and are the correct concise connector.'),
  ('63fcb9f4-2afd-56fe-a420-7a4e6f33d39e', 0, null, '**Choice A is correct.** The sentence contrasts the 1940 assumption that androstenone existed only in animals with the current understanding that it also occurs in chokecherry plants. The transition "Today," signals this shift from a past assumption to present knowledge and fits the clause that follows: "Today, scientists know that..."
**Choice B is incorrect.** "For instance," introduces an example, but the sentence is not giving an example of androstenone—it is reporting a change in scientific knowledge, so an exemplifying transition is inappropriate.
**Choice C is incorrect.** "In other words," would restate or clarify the previous idea; here the writer is presenting new, contrasting information, not a paraphrase.
**Choice D is incorrect.** "Thus," indicates a logical consequence of the prior clause, but the plant occurrence is not a deduction from the 1940 isolation; it is later discovery, so a temporal contrast like "Today," is required.
**Faster approach:** Look for whether the blank signals time/contrast, example, restatement, or consequence; match the transition type to the relationship between sentences—here the time/contrast cue "Today," fits immediately.'),
  ('3ee051e8-b112-5a7f-8ca5-d0179b8b6b4c', 2, null, '**Choice C is correct.** The sentence first names the three genres and then gives examples of plays that belong to those genres, so the blank should introduce an example; "for instance" fits that role and reads naturally: "...Much Ado About Nothing (1598-99), for instance, is classified as a comedy, whereas Richard II (1595) is classified as a history."
**Choice A is incorrect.** "In addition" implies adding another similar point; the sentence is introducing an example rather than simply adding information, so this transition is not the best fit.
**Choice B is incorrect.** "Similarly" would claim that Much Ado is like something just mentioned, but the passage is giving examples of different genres, so asserting similarity is misleading.
**Choice D is incorrect.** "However" signals contrast with the immediately preceding clause; here the author intends to introduce an example of a comedy before contrasting it with a history, so "for instance" is the appropriate choice.
**Faster approach:** Identify whether the sentence is introducing an example, adding information, or signaling contrast; match that function to the transition words ("for instance" = example, "in addition" = add, "however/whereas" = contrast, "similarly" = likeness) to pick the correct choice quickly.'),
  ('f795e118-3a73-502a-8bb9-2d9881b07be9', 3, null, '**Choice D is correct.** The sentence before the blank explains that these volcanoes look like a shield; the word "Fittingly" signals that what follows is an appropriate or apt consequence of that observation, namely that volcanologists call them "shield volcanoes." The transition correctly connects appearance to a resulting name.
**Choice A is incorrect.** "Still" suggests contrast or concession, which does not fit here because the second sentence does not contradict or limit the first; it states a natural result rather than an opposing idea.
**Choice B is incorrect.** "Besides" indicates adding another point, but the second sentence does not present an additional trait; it explains the name derived from the appearance.
**Choice C is incorrect.** "Second" indicates sequence in a list, but there is no first item presented; the passage gives a single observation and then a conclusion, not a numbered series.
**Faster approach:** Look for the logical relation between sentences (cause/result, contrast, addition, sequence); choose the transition that matches that relation—in this case a word meaning
"appropriately/resulting from" ("Fittingly").'),
  ('acc3e12e-ab7f-5c2e-9ab2-52c603433876', 3, null, '**Choice D is correct.** The sentence states that Curiosity lacked the ability to preserve samples, and the second clause explains what designers did in response when creating Perseverance; "Thus," signals that the action taken was a consequence of the earlier limitation, so it logically links the two ideas.
**Choice A is incorrect.** "Previously," would indicate a time reference but does not show the causal relationship implied between Curiosity’s limitation and the engineers'' response.
**Choice B is incorrect.** "Specifically," would narrow or clarify a preceding general statement, but the sentence needs a connector that signals consequence, not specification.
**Choice C is incorrect.** "Likewise," means "in a similar way," which would imply that Perseverance also failed to preserve samples; that contradicts the intended meaning that Perseverance was designed to address that shortcoming.
**Faster approach:** Identify whether the second clause expresses consequence, contrast, similarity, or explanation; then choose the transition that matches that logical relation (here, consequence → "Thus").'),
  ('65db930f-275d-50e3-89b3-7c94b902c334', 2, null, '**Choice C is correct.** The sentence contrasts two groups by noting that one follows the tejano tradition and the other follows the banda tradition; the transition "however," signals this contrast naturally and connects the clauses smoothly: "The former... The latter, however, follows..."
**Choice A is incorrect.** "Therefore," indicates a result or conclusion, which does not fit because the sentence is presenting an alternative/tradeoff rather than a consequence.
**Choice B is incorrect.** "To this end," signals purpose or intention, which is inappropriate here because the sentence is contrasting two different traditions, not describing intent.
**Choice D is incorrect.** "In other words," signals a restatement or clarification of the preceding idea; it would wrongly imply that the banda tradition is a rephrasing of tejano, rather than a contrasting tradition.
**Faster approach:** Look for contrast cues like "former/latter"; when two items are being contrasted, a transitional word that signals contrast (e.g., "however," "on the other hand") is usually correct.'),
  ('6dcf3c60-73a6-52ef-8019-29536acd5f20', 0, null, '**Choice A is correct.** The sentence needs a locative transition pointing to the mouth of the Susitna River; "There," signals location and smoothly connects the preceding clause (the river’s course) to the clause that specifies where the water empties. The phrase "There, at the Susitna’s mouth, hundreds of kilometers from the source, the water empties into the Gulf of Alaska" is grammatically and logically coherent.
**Choice B is incorrect.** "For instance," introduces an example, but the sentence is not giving an example of the prior statement; it is continuing the description of location, so this transition is inappropriate.
**Choice C is incorrect.** "Regardless," signals concession or contrast, which does not fit the factual, locational continuation needed here.
**Choice D is incorrect.** "Instead," indicates an alternative or substitute, but the sentence describes the actual path and destination of the water, not an alternative, so this choice is unsuitable.
**Faster approach:** For location-based continuations, pick a locative transition such as "There,"; eliminate choices that signal example, contrast, or substitution.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;
